  workflow_funnel_stats?: ApplicationAnalyticsWorkflowFunnel;
  /** Active time users spent verifying, ignoring idle gaps. An empty object when there is no data. */
  verification_time_stats?: ApplicationAnalyticsVerificationTimeStats;
  verification_time_time_series?: ApplicationAnalyticsVerificationTimePoint[];
  /** Keyed by feature (`ID_VERIFICATION`, `LIVENESS`, `FACEMATCH`, `AML`, `PROOF_OF_ADDRESS`, `PHONE`, `EMAIL`, `NFC`, `LOCATION`, `DATABASE_VALIDATION`, `QUESTIONNAIRE` and the KYB features). `total` is the sessions that reached the feature; `risks` counts sessions per warning code and level. */
