  original_status_time_series?: ApplicationAnalyticsOriginalStatusPoint[];
  demographic_stats?: ApplicationAnalyticsDemographicStats;
  demographic_time_series?: ApplicationAnalyticsDemographicPoint[];
  /** Top five of each, most sessions first. */
  device_details?: ApplicationAnalyticsDeviceDetails;
  device_time_series?: ApplicationAnalyticsDevicePoint[];
  /** Entries of a list widget. `country_distribution` (KYC): `country`, `country_code`, `session_count`. `conversion_by_country`: `country`, `country_code`, `finished`, `approved`. `time_series`: `date`, `value`. `status_time_series`: `date`, `approved`, `declined`, `flagged`. `breakdown`: `transaction_type` or `action_type` with `count` and `volume`, or `tag_id`, `tag_name`, `count`. `leaderboard`: `rule_title`, `trigger_count` or `assignee`, `handled_count`, `average_processing_seconds`, each with `approved_percentage`, `declined_percentage`, `flagged_percentage`. `histogram`: `score`, `count`. */
  items?: Record<string, unknown>[];
