/** A blocklist, allowlist or custom list of one application. */
export interface ComplianceList {
  /** List identifier. Use it as `list_uuid` in the list and entry endpoints, and as the value of a workflow or transaction rule condition with `value_type: "list"`. */
  uuid: string;
  /** List name, unique among the application's lists. */
  name: string;
  /** Free-text description. Empty string when not set. */
  description: string;
  /** `blocklist`: a match declines the session or transaction (system lists only, one per entry type). `allowlist`: matching items are trusted, for example a face allowlist skips the duplicated-face action; never overrides a blocklist match. `custom`: used in workflow and transaction rule conditions (`value_type: "list"`). */
  list_type: "blocklist" | "allowlist" | "custom" | (string & {});
  /** What the list holds: `face`, `document` (document number), `phone`, `email`, `ip_address` (IP address or CIDR range), `device_fingerprint`, `wallet_address`, `bank_account`, `country` (ISO 3166-1 alpha-3), `user` or `business` (your `vendor_data`), or `key` (any string). It decides how entry values are validated and matched. */
  entry_type:
    | "face"
    | "document"
    | "phone"
    | "email"
    | "ip_address"
    | "device_fingerprint"
    | "wallet_address"
    | "bank_account"
    | "country"
    | "user"
    | "business"
    | "key"
    | (string & {});
  /** `true` for the lists Didit provisions: one blocklist per entry type (`face`, `document`, `phone`, `email`, `ip_address`, `device_fingerprint`, `wallet_address`, `bank_account`, `user`, `business`), the **High Risk Countries** custom list, and system allowlists. System lists cannot be renamed, edited or deleted; you can add and delete their entries. */
  is_system: boolean;
  /** Number of entries currently in the list. */
  entry_count: number;
  /** When the newest current entry was added. `null` for an empty list. */
  last_entry_added_at: Date | null;
  /** When the list was created. */
  created_at: Date;
  /** When the list was last updated. */
  updated_at: Date;
}

/** One value in a list. */
export interface ComplianceListEntry {
  /** Entry identifier. Use it as `entry_uuid` in Delete a list entry. */
  uuid: string;
  /** The listed value: a phone number in E.164, an email address, a document number, an IP address or CIDR range, a device fingerprint, a wallet address, a bank account, an ISO 3166-1 alpha-3 country code, a `vendor_data`, any string on a `key` list, or the UUID of the stored face on a face list. Values you send are stored in lower case, except phone numbers and country codes. Matching is case-insensitive. */
  value: string;
  /** Human-readable label. Didit fills it for entries taken from a session (for example the holder's name and document number) when you send none. */
  display_label: string | null;
  /** Free-text note. Empty string when not set. */
  comment: string;
  /** Who added the entry: `api` (an API key), a console user's email address or `console`, `system` or `migration` (entries Didit created), or `rule` (a transaction or monitoring rule action). */
  added_by: string | null;
  /** Verification session the entry was taken from. `null` when the entry was added by value. */
  reference_session_id: string | null;
  /** Application-scoped number of that session, as shown in the console. */
  reference_session_number: number | null;
  /** `kyc` for a person verification session, `kyb` for a business verification session, `null` when there is no session. */
  reference_session_type: "kyc" | "kyb" | (string & {}) | null;
  /** The record the entry stands for: the face, document, phone or email record read from a session, the face created by Upload a face to a list, or the UUID you sent (for example a transaction UUID or a user's `didit_internal_id`). */
  reference_object_uuid: string | null;
  /** Extra context. Holds the keys Didit sets (listed here) merged with any `metadata` you sent when creating the entry, returned as stored. `null` when there is none. */
  metadata: ComplianceListEntryMetadata | null;
  /** When the entry was added. */
  created_at: Date;
}

/** Extra context. Holds the keys Didit sets (listed here) merged with any `metadata` you sent when creating the entry, returned as stored. `null` when there is none. */
export interface ComplianceListEntryMetadata {
  /** Face entries: short-lived signed URL, issued again on every call; `null` for a scoped API key without `media: read`. Absent when no image belongs to the entry. */
  reference_image_url?: string;
  /** Document entries that carry a document front image: short-lived signed URL, issued again on every call; `null` for a scoped API key without `media: read`. */
  front_image_url?: string;
  /** Document entries taken from a session: holder's full name. */
  full_name?: string;
  /** Document entries taken from a session: ISO 3166-1 alpha-3 issuing country. */
  issuing_state?: string;
  /** Document entries taken from a session: document type code, for example `P`, `ID` or `DL`. */
  document_type?: string;
  /** Document entries taken from a session: issuing state or province of a regionally issued document, empty when not applicable. Not set by Add session items to the blocklist. */
  region?: string;
  /** Document entries taken from a session: the document number. */
  document_number?: string;
  /** Face entries taken from a document-capture selfie: which selfie. Absent for liveness faces. */
  face_image_source?: "front_image_camera_front" | "back_image_camera_front" | (string & {});
  /** Face entries taken from a document-capture selfie: the ID verification node the selfie came from. */
  reference_node_id?: string | null;
  /** Device fingerprint entries taken from a session: how the fingerprint was derived. `persistent_id` identifies one device; `composite_hash` and `legacy_fp` can be shared by devices of the same model. */
  fingerprint_tier?:
    "persistent_id" | "composite_hash" | "legacy_fp" | "unknown" | (string & {}) | null;
  /** `true` on a face entry uploaded in a sandbox application; such an entry matches nothing. */
  sandbox?: boolean;
  /** Set by you: what `reference_object_uuid` points to, so the console links back to it. */
  reference_type?: "transaction" | "vendor_user" | "vendor_business" | (string & {});
  /** Set by you: identifier of the source record. */
  reference_id?: string;
  [key: string]: unknown;
}

