/** One override of a check (feature) status made with `PATCH /v3/session/{sessionId}/features/{nodeId}/update-status/`: what it changes, whether it applied or still waits for the person to finish the flow, who asked and why. */
export interface FeatureStatusOverride {
  /** Identifier of the override. Pass it to the cancel endpoint. */
  id: string;
  /** The workflow node the request named (`default` for a step without a node). */
  node_id: string;
  /** The `feature_type` the request passed, or an empty string when it passed none. */
  feature_type: string;
  /** The kind of check that was overridden, for example `KYC`, `Face`, `AML` or `GeolocationCheck`. */
  feature_model: string;
  /** The check's status when the override was requested. */
  previous_status:
    "Not Finished" | "Approved" | "Declined" | "In Review" | "Resub Requested" | (string & {});
  /** The status the override sets. */
  new_status: "Approved" | "Declined" | "In Review" | (string & {});
  /** `applied`: the check has the new status. `pending_until_flow_finishes`: the override waits and applies when the person finishes the flow. `cancelled`: it waited and never applied (see `cancel_reason`). */
  state: "applied" | "pending_until_flow_finishes" | "cancelled" | (string & {});
  /** `true` when the override applied at once while the person was still in the flow. */
  forced: boolean;
  /** The `comment` sent with the request, or `null`. */
  reason: string | null;
  /** Who requested the override, or `null` when that is not known. */
  requested_by: FeatureStatusOverrideRequestedBy | null;
  /** When the override was requested. */
  requested_at: Date;
  /** When the check took the new status, or `null` while it waits or once it is cancelled. */
  applied_at: Date | null;
  /** When a waiting override was cancelled, or `null`. */
  cancelled_at: Date | null;
  /** Why a waiting override never applied, or `null`. `cancelled_by_reviewer`: cancelled with the cancel endpoint. `replaced`: a newer override on the same check replaced it. `check_changed`: the person redid the check before finishing the flow. `session_closed`: the session left the flow before the person finished it (abandoned, expired, or decided mid-flow). */
  cancel_reason:
    | "cancelled_by_reviewer"
    | "replaced"
    | "check_changed"
    | "session_closed"
    | (string & {})
    | null;
}

/** Who requested the override, or `null` when that is not known. */
export interface FeatureStatusOverrideRequestedBy {
  /** Email of the console user, or `null` for API keys and the system. */
  email?: string | null;
  /** Display name of the requester, or `null`. */
  name?: string | null;
  /** Who made the request: a console user, an API key, or Didit itself. */
  type?: "CONSOLE_USER" | "API_KEY" | "SYSTEM" | (string & {});
}

