  /** Status of the child KYC session. A deleted session keeps the status it had when it was deleted. */
  kyc_session_status?:
    | "Not Started"
    | "In Progress"
    | "Approved"
    | "Declined"
    | "In Review"
    | "Expired"
    | "Abandoned"
    | "Kyc Expired"
    | "Resubmitted"
    | "Awaiting User"
    | (string & {})
    | null;
  /** Hosted link of the child KYC session. `null` when there is none or it was deleted, and for a scoped API key without `sessions: write`. */
  kyc_session_url?: string | null;
  /** The child KYC session was deleted, so it can never settle. */
  kyc_session_deleted: boolean;
  /** Child KYB session (company parties). */
  kyb_sub_session_id?: string | null;
  /** Status of the child KYB session. */
  kyb_sub_session_status?:
    | "Not Started"
    | "In Progress"
    | "Approved"
    | "Declined"
    | "In Review"
    | "Expired"
    | "Abandoned"
    | "Kyc Expired"
    | "Resubmitted"
    | "Awaiting User"
    | (string & {})
    | null;
  /** Hosted link of the child KYB session, with the same `null` rules as `kyc_session_url`. */
  kyb_sub_session_url?: string | null;
  /** Company-party counterpart of `kyc_session_deleted`. */
  kyb_sub_session_deleted: boolean;
  /** Type of the workflow the child session runs. */
  verification_workflow_type?:
    | "kyc"
    | "kyb"
    | "adaptive_age_verification"
    | "biometric_authentication"
    | "address_verification"
    | "questionnaire_verification"
    | "email_verification"
    | "phone_verification"
    | (string & {})
    | null;
  /** Workflow the child session runs. */
