/** Normalized phone-intelligence block. Present only when the intelligence add-on ran for this lookup; when present it is also exposed under the `enrichment` alias with identical values. */
export interface PhoneIntelligence {
  /** Normalized 0-100 risk score. Higher is riskier. */
  score?: number | null;
  /** `Low`, `Medium` or `High`, derived from the score. */
  phone_type_risk?: string | null;
  /** Inverse of the score, for dashboards that prefer higher is better. */
  phone_trust_index?: number | null;
  /** Stability of the line's network. */
  network_stability_index?: number | null;
  /** `true` when the number looks disposable or virtual. */
  is_disposable?: boolean | null;
  /** `true` when the number has moved carrier. */
  is_ported?: boolean | null;
  /** `true` when the port happened recently. */
  is_recently_ported?: boolean | null;
  /** Line classification reported by the lookup (e.g., `mobile`). */
  carrier_type?: string | null;
  /** Machine-readable codes explaining the score. Values can grow over time, so do not reject unknown codes. */
  reason_codes?: string[];
}

/** Another session of your application that used the same phone number with a different `vendor_data`. */
export interface PhoneMatchItem {
  /** Session id of the other verification that used this phone number. */
  session_id?: string;
  /** Human-friendly sequential number of that session. */
  session_number?: number;
  /** `vendor_data` of that session. */
  vendor_data?: string | null;
  /** When that session was created (`YYYY-MM-DDTHH:MM:SSZ`). */
  verification_date?: string;
  /** The matched phone number. */
  phone_number?: string;
  /** Status of that session (e.g., `Approved`, `Declined`, `In Progress`). */
  status?: string;
  /** Whether the phone number is on your application's blocklist. */
  is_blocklisted?: boolean;
  /** For API-type sessions, the standalone API that created it; `null` for regular verification sessions. */
  api_service?: string | null;
  /** Where the match was found. Usually `session`; a blocklist hit via an organization list entry uses `list_entry`. */
  source?: string;
}

export interface PhoneRiskResponse {
  /** Id of the API session created for this request. Store it with `vendor_data` if you need to correlate the result with later webhooks or console activity. */
  request_id: string;
  /** Final decision for this API session. Normally `Approved`; the risk evaluation can produce `In Review` or `Declined`. */
  status: "Approved" | "In Review" | "Declined" | (string & {});
  /** Echo of the `vendor_data` you sent, `null` when you did not send one. */
  vendor_data?: string | null;
  /** Echo of the `metadata` you sent, `null` when you did not send one. */
  metadata?: Record<string, unknown> | null;
  /** Timestamp of this response. */
  created_at: Date;
  /** Normalized phone report, the same block used by Phone Verification responses. */
  phone?: PhoneRiskResponsePhone;
}

/** Normalized phone report, the same block used by Phone Verification responses. */
export interface PhoneRiskResponsePhone {
  /** Decision for this phone number. Mirrors the top-level `status`. */
  status: "Approved" | "In Review" | "Declined" | (string & {});
  /** Country calling code with leading `+` (e.g., `+1`). */
  phone_number_prefix?: string;
  /** National number without the country calling code. */
  phone_number?: string;
  /** Complete number in E.164 format. */
  full_number?: string;
  /** ISO 3166-1 alpha-2 country of the number. */
  country_code?: string | null;
  /** Full country name derived from `country_code`. */
  country_name?: string;
  /** Current network serving the number. `null` when the lookup could not resolve a carrier. */
  carrier?: PhoneRiskResponsePhoneCarrier | null;
  /** `true` when the number belongs to a temporary or burner number service. */
  is_disposable?: boolean;
  /** `true` when the line type is virtual (`voip`, `isp`, or `vpn`). */
  is_virtual?: boolean;
  /** OTP channel of the underlying verification. `null` for risk lookups, which never send a code. */
  verification_method?: string | null;
  /** OTP sends for this number. `0` for risk lookups. */
  verification_attempts?: number;
  /** When the number was last verified by an OTP. `null` for risk lookups. */
  verified_at?: Date | null;
  /** Risk warnings recorded for this request. Empty array when there are none. */
  warnings?: RiskWarning[];
  /** Chronological audit trail of the request. Empty array for risk lookups without send events. */
  lifecycle?: RiskLifecycleEvent[];
  /** Other sessions of your application where the same phone number was used by a different user (different `vendor_data`). Up to 5 entries. Empty array when there are no matches. */
  matches?: PhoneMatchItem[];
  /** Normalized phone-intelligence block. Present only when the intelligence add-on ran for this lookup; when present it is also exposed under the `enrichment` alias with identical values. */
  phone_intelligence?: PhoneIntelligence;
  /** Normalized phone-intelligence block. Present only when the intelligence add-on ran for this lookup; when present it is also exposed under the `enrichment` alias with identical values. */
  enrichment?: PhoneIntelligence;
  /** Social footprint of the phone number: the online platforms it is registered on. Present only when `enable_social` was set and the check completed. Every count may be null when no data was returned for it. `profiles_registered: 0` means the platforms were checked and the phone number was found on none of them - a valid, billable answer and a common synthetic-identity signal. */
  phone_social?: PhoneSocialFootprint | null;
}

/** Current network serving the number. `null` when the lookup could not resolve a carrier. */
