/** One entry in a session's review / activity feed. Status changes carry `previous_status`, `new_status`, `previous_value`, `new_value`, and `changed_fields`; comments carry `comment` and (for Console comments) `mentioned_emails`; the remaining fields are `null` or empty when they do not apply to the activity type. */
export interface ReviewItem {
  /** Unique identifier of this feed entry. */
  uuid?: string;
  /** What kind of activity this entry records. `STATUS_UPDATED` rows come from manual decisions (`PATCH /v3/session/{session_id}/update-status/`) and from entries added via `POST …/reviews/` (which default to this type even when no status is recorded). `COMMENT` rows come from Console reviewers; Console detail-page views are also stored as `COMMENT` rows flagged with `metadata.system_event = "DETAIL_VIEWED"`. The remaining types track data edits, file changes, tags, and AML monitoring activity. STATUS_UPDATED rows are also written by system actors (e.g. AML ongoing monitoring with actor_type SYSTEM, and automatic feature-status updates), not only by the update-status endpoint and manual review posts. `FEATURE_OVERRIDE_PENDING`, `FEATURE_OVERRIDE_APPLIED` and `FEATURE_OVERRIDE_CANCELLED` record an override of one check's status (`PATCH /v3/session/{session_id}/features/{node_id}/update-status/`): requested to wait for the flow to finish, applied, or cancelled. They carry the check's status in `previous_value` / `new_value` (`{"status": ...}`), leave `previous_status` and `new_status` `null`, and name the override in `metadata` (`feature_override_id`, `node_id`, `feature_model`, `forced`, `state`, `cancel_reason`). The entry for the request carries the reviewer's `comment`; an override applied when the flow finishes is recorded with `actor_type` `SYSTEM`. */
  activity_type?:
    | "COMMENT"
    | "STATUS_UPDATED"
    | "KYC_DATA_UPDATED"
    | "POA_DATA_UPDATED"
    | "FILE_ADDED"
    | "FILE_REMOVED"
    | "AML_ONGOING_MATCH"
    | "AML_STATUS_UPDATED"
    | "AML_HIT_STATUS_UPDATED"
    | "KYB_DATA_UPDATED"
    | "KYB_DOCUMENT_UPLOADED"
    | "TAG_ADDED"
    | "TAG_REMOVED"
    | "FEATURE_OVERRIDE_PENDING"
    | "FEATURE_OVERRIDE_APPLIED"
    | "FEATURE_OVERRIDE_CANCELLED"
    | (string & {});
  /** Human-readable author label, resolved in order: actor's full name → Console account identifier → local part of `actor_email` → `"API Client"` (for `API_KEY` actors) → `"System"` (for `SYSTEM` actors) → `"Unknown"`. Entries created via `POST …/reviews/` always display `"Unknown"` because that endpoint records no actor attribution. */
  actor_display?: string;
  /** Email of the Console user who performed the action. `null` for API-key and system actors. */
  actor_email?: string | null;
  /** Who performed the action: an API key, a Console user, or Didit itself (`SYSTEM`, e.g. AML ongoing monitoring). Entries created via `POST …/reviews/` carry the default `CONSOLE_USER` regardless of the caller. */
  actor_type?: "API_KEY" | "CONSOLE_USER" | "SYSTEM" | (string & {});
  /** Session status recorded by this entry (for status updates). `null` for comments and data-change entries. */
  new_status?:
    | "Not Started"
    | "In Progress"
    | "Approved"
    | "Declined"
    | "In Review"
    | "Expired"
    | "Abandoned"
    | "Kyc Expired"
    | "Resubmitted"
    | "Awaiting User"
    | (string & {})
    | null;
  /** Status the session had before the change. Populated on `STATUS_UPDATED` entries written by the update-status endpoint; `null` on entries added via `POST …/reviews/`. Also populated on system-written STATUS_UPDATED rows. */
  previous_status?:
    | "Not Started"
    | "In Progress"
    | "Approved"
    | "Declined"
    | "In Review"
    | "Expired"
    | "Abandoned"
    | "Kyc Expired"
    | "Resubmitted"
    | "Awaiting User"
    | (string & {})
    | null;
  /** Free-text note attached to the entry, or `null`. */
  comment?: string | null;
  /** Console users `@email`-mentioned in the comment. Always empty for entries created via this API - mention processing is a Console-only feature. */
  mentioned_emails?: string[];
  /** Snapshot of the changed data before the action, e.g. `{"status": "In Review"}` on a status change. `null` when nothing was changed. */
  previous_value?: Record<string, unknown> | null;
  /** Snapshot of the changed data after the action, e.g. `{"status": "Approved"}`. `null` when nothing was changed. */
  new_value?: Record<string, unknown> | null;
  /** Names of the fields modified by this activity (e.g. `["status"]`). Empty for comments and for entries added via `POST …/reviews/`. */
  changed_fields?: string[];
  /** Extra context for system-generated entries. Console detail-page views carry `{"system_event": "DETAIL_VIEWED", "detail_type": "verification"}` so they can be filtered out of notification logic. `null` for ordinary entries. */
  metadata?: Record<string, unknown> | null;
  /** When the entry was written, ISO 8601 UTC. */
  created_at?: Date;
}

