  /** True for analyst-created document request placeholders awaiting an upload. */
  is_requested?: boolean;
  ocr_data?: Record<string, unknown> | null;
  /** True for documents uploaded from the console rather than the end-user flow. Console uploads never change the feature-level aggregate status. */
  is_console_upload?: boolean;
