  /** Accepted document subtype code from the workflow document settings, including the document region when applicable. Examples: `ID_CARD_GENERIC`, `QUEENSLAND_DRIVER_LICENSE_GENERIC`. */
  document_subtype?: string | null;
  /** Document identification number */
  document_number?: string;
  /** Personal identification number */
  personal_number?: string;
  /** URL of the portrait image */
  portrait_image?: string;
  /** URL of the front document image */
  front_image?: string;
  /** URL of the front document video */
  front_video?: string;
  /** URL of the back document image */
  back_image?: string;
  /** URL of the back document video */
  back_video?: string;
