  /** Face match score between the portrait extracted from the back document image and the front camera image */
  back_image_camera_front_face_match_score?: number | null;
  /** Previous sessions or face blocklist entries whose face matched the selfie the front camera took during document capture (Silent Capture Face Search). Same entry format as `liveness_checks[].matches`. `null` for sessions created before this field existed or when the search did not run; an empty array when it ran and found nothing. `match_image_url` is a presigned URL that expires. */
  document_selfie_face_matches?: SessionDecisionIdVerificationsDocumentSelfieFaceMatches[] | null;
  /** Quality metrics for the front document image. Each sub-score ranges from 0 to 100. */
