/** One liveness report - the full report for a single liveness pass. */
export interface SessionDecisionLivenessChecks {
  /** Workflow graph node id of the liveness step that produced this report. */
  node_id?: string;
  /** Feature-level status of this liveness step. Independent of the top-level session `status` - a session can reach its overall decision while an individual feature stays `In Review`. */
  status?:
    "Not Finished" | "Approved" | "Declined" | "In Review" | "Resub Requested" | (string & {});
  /** Method used for liveness detection */
  method?: string;
  /** Confidence score of the liveness check */
  score?: number;
  /** URL of the reference image used */
  reference_image?: string;
  /** URL of the liveness check video */
  video_url?: string;
  /** Estimated age of the person */
  age_estimation?: number;
  /** Similar faces found by the duplicate-face search (top matches, blocklisted/allowlisted entries first). Each entry's `source` tells you where the matching face came from: `session` (another verification session), `imported` (a face uploaded against a vendor user), `list_entry` (an org-managed allow/block list face), or `retained_template` (an image-free biometric template stored on a User, listed under `/v3/biometric-templates/`). `session_id`, `session_number`, `status` and `api_service` are `null` for non-session sources. `imported` matches still populate `vendor_data`, `verification_date` and - when the vendor user has a name on file - `user_details` (with `full_name` only) from the vendor-user record; `retained_template` matches populate `vendor_user_id`, `vendor_data`, `biometric_template_id` and `verification_date`, while their image and identity fields are `null`; `list_entry` matches return all of these as `null`. */
  matches?: SessionDecisionLivenessChecksMatches[];
  warnings?: SessionDecisionLivenessChecksWarnings[];
  /** Face image quality score (0-100%). Only available for passive liveness. */
  face_quality?: number | null;
  /** Face luminance/brightness score (0-100%). Only available for passive liveness. */
  face_luminance?: number | null;
}

export interface SessionDecisionLivenessChecksMatches {
  /** Session ID of the matching face. `null` when `source` is `imported`, `list_entry`, or `retained_template`. */
  session_id?: string | null;
  session_number?: number | null;
  /** Face similarity between the two images, clamped to 0–100. */
  similarity_percentage?: number;
  /** `vendor_data` of the matching session or linked User for imported and retained-template faces. */
  vendor_data?: string | null;
  /** Linked User id for `imported` and `retained_template` matches and for session matches linked to a User. `null` for list entries and sessions without a User. */
  vendor_user_id?: string | null;
  /** Id of the retained biometric template. Set only when `source` is `retained_template`; `null` otherwise. */
  biometric_template_id?: string | null;
  /** When the matching face was captured, or when a retained template was created. `null` for list entries. */
  verification_date?: Date | null;
  /** Identity data from the matching session or imported User profile. Always `null` for `retained_template` and `list_entry` matches. */
  user_details?: SessionDecisionLivenessChecksMatchesUserDetails | null;
  /** Reference image for image-backed matches. Always `null` for `retained_template` matches because retained templates contain no image. */
  match_image_url?: string | null;
  /** Lifecycle status of the matching session. `null` for non-session sources. */
  status?: string | null;
  /** Whether the matching face is on a blocklist. */
  is_blocklisted?: boolean;
  /** Whether the matching face is on an allowlist. */
  is_allowlisted?: boolean;
  /** Standalone API service of the matching session (e.g. `PASSIVE_LIVENESS`, `FACE_MATCH`); `null` for workflow sessions and non-session sources. */
  api_service?: string | null;
  /** Origin of the matching face: `session`, `imported` (User face upload), `list_entry` (allow/block list), or `retained_template` (an image-free biometric template stored on a User, listed under `/v3/biometric-templates/`). */
  source?: "session" | "imported" | "list_entry" | "retained_template" | (string & {});
}

