/** One NFC report: the full report for a single chip read (an ICAO 9303 ePassport or eID chip, or a Japan My Number Card read through JPKI). */
export interface SessionDecisionNfcVerifications {
  /** Workflow graph node id of the NFC step that produced this report. Use it to correlate the report with the workflow definition. */
  node_id?: string;
  /** Feature-level status of this NFC step. Independent of the top-level session `status` - a session can reach its overall decision while an individual feature stays `In Review`. */
  status?:
    "Not Finished" | "Approved" | "Declined" | "In Review" | "Resub Requested" | (string & {});
  /** `true` when this NFC step was explicitly skipped instead of read; `skip_reason` says why. */
  is_nfc_skipped?: boolean;
  /** Why this NFC step was skipped. Only set when `is_nfc_skipped` is `true`. Same taxonomy as the session-level `nfc_skip_reason`, which additionally covers the cases where NFC never produced a report at all. */
  skip_reason?:
    | "USER_SKIPPED"
    | "DOCUMENT_WITHOUT_CHIP"
    | "CHIP_CERTIFICATE_UNAVAILABLE"
    | "DEVICE_WITHOUT_NFC"
    | "INTEGRATION_WITHOUT_NFC_ACCESS"
    | "MRZ_KEY_UNAVAILABLE"
    | "JPKI_UNAVAILABLE"
    | (string & {})
    | null;
  /** How the NFC step reads the chip. `icao`: ICAO 9303 ePassport or eID chip, opened with the access key from the MRZ. `jpki`: Japan My Number Card, where the card signs a one-time challenge after the holder enters the card PIN in a native SDK; the result is under `jpki`. Also set on skipped steps, so you can tell a skipped My Number Card read apart. */
  chip_protocol?: "icao" | "jpki" | (string & {});
  /** What a Japan My Number Card read through JPKI proved. Present when `chip_protocol` is `jpki` and the card was read. `null` for ICAO chips, for skipped steps, and when the NFC step closed without any card read (that case raises `JPKI_SIGNATURE_INVALID`). Never carries the certificates, their serial numbers, the signatures or the 12-digit My Number. */
  jpki?: SessionDecisionNfcVerificationsJpki | null;
  /** Presigned URL to the portrait read from the chip (ICAO DG2). `null` for a JPKI read (`chip_protocol: "jpki"`) and for skipped steps. */
  portrait_image?: string | null;
  /** Presigned URL to the holder's signature image read from the chip (ICAO DG7), when the chip stores one. `null` for a JPKI read (`chip_protocol: "jpki"`) and for skipped steps. */
  signature_image?: string | null;
  /** Personal data parsed from the ICAO chip's Data Groups. `null` for a JPKI read (`chip_protocol: "jpki"`) and for skipped steps. */
  chip_data?: SessionDecisionNfcVerificationsChipData | null;
  /** ICAO passive authentication: SOD signature (`sod_integrity`) and Data Group hashes (`dg_integrity`). `null` for a JPKI read, which reports its proof under `jpki`. */
  authenticity?: SessionDecisionNfcVerificationsAuthenticity | null;
  /** Summary of the ICAO Document Signer Certificate. `null` for a JPKI read (`chip_protocol: "jpki"`) and for skipped steps. */
  certificate_summary?: SessionDecisionNfcVerificationsCertificateSummary | null;
  warnings?: SessionDecisionNfcVerificationsWarnings[];
}

/** ICAO passive authentication: SOD signature (`sod_integrity`) and Data Group hashes (`dg_integrity`). `null` for a JPKI read, which reports its proof under `jpki`. */
export interface SessionDecisionNfcVerificationsAuthenticity {
  sod_integrity?: boolean;
  dg_integrity?: boolean;
}

/** Summary of the ICAO Document Signer Certificate. `null` for a JPKI read (`chip_protocol: "jpki"`) and for skipped steps. */
export interface SessionDecisionNfcVerificationsCertificateSummary {
  issuer?: string;
  subject?: string;
  serial_number?: string;
  not_valid_after?: Date;
  not_valid_before?: Date;
}

/** Personal data parsed from the ICAO chip's Data Groups. `null` for a JPKI read (`chip_protocol: "jpki"`) and for skipped steps. */
export interface SessionDecisionNfcVerificationsChipData {
  document_type?: string;
  issuing_country?: string;
  document_number?: string;
  expiration_date?: string;
  first_name?: string;
  last_name?: string;
  birth_date?: string;
  gender?: string;
  nationality?: string;
  address?: string;
  place_of_birth?: string;
}

/** What a Japan My Number Card read through JPKI proved. Present when `chip_protocol` is `jpki` and the card was read. `null` for ICAO chips, for skipped steps, and when the NFC step closed without any card read (that case raises `JPKI_SIGNATURE_INVALID`). Never carries the certificates, their serial numbers, the signatures or the 12-digit My Number. */
export interface SessionDecisionNfcVerificationsJpki {
  /** The card certificates read. `user_authentication` (4-digit PIN) is always read; `signature` (signature PIN) is read when the NFC node's `jpki_request_attributes` setting is on. */
  certificate_types?: ("user_authentication" | "signature" | (string & {}))[];
  /** `true` when every certificate read chains to the JPKI certification authority, is inside its validity period and is a My Number Card certificate of its type. */
  chain_valid?: boolean;
  /** `true` when every signature the card made over the one-time challenge verifies. The card only signs after its PIN is entered, so this proves possession of the card and knowledge of the PIN. */
  signature_valid?: boolean;
  /** `good` when the revocation check confirmed every certificate is valid, `revoked` when any certificate is revoked (for example a card reported lost), `unchecked` when no revocation answer was available. `unchecked` is never treated as `good`: the NFC node's `jpki_revocation_unchecked_action` decides the outcome (default `REVIEW`). */
  revocation_status?: "good" | "revoked" | "unchecked" | (string & {});
  /** Generation of the JPKI certification authority that issued the certificates, for example `2023`. `null` when no certificate chains to one. */
  ca_generation?: string | null;
  /** The earliest expiry among the certificates read. */
  certificate_expires_at?: Date | null;
  /** Per-certificate results, one entry per certificate read. */
  certificates?: SessionDecisionNfcVerificationsJpkiCertificates[];
  /** The holder's data from the signature certificate, once its chain is valid. `null` when the signature certificate was not requested or did not chain to the JPKI certification authority. */
  attributes?: SessionDecisionNfcVerificationsJpkiAttributes | null;
  /** `true` when the attributes match the data read from the photo of the same card, `false` when any attribute differs (`JPKI_AND_OCR_DATA_NOT_SAME`), `null` when nothing could be compared, including whenever `attributes` is `null`. */
  attributes_match_ocr?: boolean | null;
  /** Names of the attributes that differ from the photo data, never their values. Empty when everything compared matches. */
  mismatched_attributes?: ("full_name" | "date_of_birth" | "gender" | "address" | (string & {}))[];
}

/** The holder's data from the signature certificate, once its chain is valid. `null` when the signature certificate was not requested or did not chain to the JPKI certification authority. */
export interface SessionDecisionNfcVerificationsJpkiAttributes {
  /** Name as registered, usually in Japanese script. */
  full_name?: string | null;
  /** Date of birth, `YYYY-MM-DD`. `null` when the registered date is incomplete. */
  date_of_birth?: string | null;
  /** `M`, `F`, or `null` when not registered. */
  gender?: "M" | "F" | (string & {}) | null;
  /** Registered address. */
  address?: string | null;
  /** Position string marking the characters of `full_name` that were replaced by a substitute because the original character is outside the standard character set. `null` when none were replaced. */
  name_substitute_characters?: string | null;
  /** Position string marking substitute characters in `address`, as for `name_substitute_characters`. */
  address_substitute_characters?: string | null;
}

/** What one certificate read from the card proved. Never the certificate itself or its serial number. */
export interface SessionDecisionNfcVerificationsJpkiCertificates {
  /** Which card certificate this entry describes. */
  type?: "user_authentication" | "signature" | (string & {});
  /** `true` when the certificate chains to the JPKI certification authority of its type, is inside its validity period and is a My Number Card certificate of that type. */
  chain_valid?: boolean;
  /** `true` when the card's signature over the one-time challenge verifies against this certificate. */
  signature_valid?: boolean;
  /** Generation of the JPKI certification authority that issued the certificate, for example `2023`. `null` when no trusted issuer was found. */
  ca_generation?: string | null;
  /** Start of the certificate's validity period. `null` when the certificate could not be read. */
  not_valid_before?: Date | null;
  /** End of the certificate's validity period. `null` when the certificate could not be read. */
  not_valid_after?: Date | null;
  /** Why `chain_valid` is `false`: `unreadable_certificate`, `untrusted_issuer` (not issued by the JPKI certification authority of its type), `expired`, `not_yet_valid`, `wrong_policy` (not a My Number Card certificate of that type) or `key_usage` (the key may not sign). `null` when the chain is valid. */
  failure?:
    | "unreadable_certificate"
    | "untrusted_issuer"
    | "expired"
    | "not_yet_valid"
    | "wrong_policy"
    | "key_usage"
    | (string & {})
    | null;
}

