/** The name comparison that decided the transfer, or null until one ran. While the parties are masked, and on the other customer's copy of an INTERNAL exchange, `transfer_name`, `compared_name`, `matched_names` and `mismatched_names` are hidden. `score` and `matched` can disagree: `matched` follows the strictness, `score` is the similarity of the two full names. */
export interface TravelRuleNameMatch {
  /** Similarity of the two full names, 0 to 100. 0 when either name is blank. */
  score?: number;
  /** Whether the names satisfy `strictness`. The transfer's outcome follows `data_match`, which compares every field, so a transfer can be COUNTERPARTY_MISMATCHED_DATA while this is true. */
  matched?: boolean;
  /** How `matched` was decided: none (`NONE`), exact_token (`STRICT`), token_subset (`DEFAULT`), token_containment (`CONTAINS`) or sequence_ratio (`FUZZY`). */
  method?:
    | "none"
    | "exact_token"
    | "token_subset"
    | "token_containment"
    | "sequence_ratio"
    | (string & {});
  strictness?: "NONE" | "STRICT" | "CONTAINS" | "DEFAULT" | "FUZZY" | (string & {});
  /** wallet_holder: the holder recorded for the wallet. counterparty_vasp: the name the counterparty answered on the email response page, or the Didit Test VASP's answer in sandbox. */
  compared_with?: "wallet_holder" | "counterparty_vasp" | (string & {});
  /** The name on the transfer. */
  transfer_name?: string;
  /** The name it was compared with. */
  compared_name?: string;
  /** Words of `transfer_name` found in `compared_name`. */
  matched_names?: string[];
  /** Words of `transfer_name` missing from `compared_name`, then words of `compared_name` missing from `transfer_name`. */
  mismatched_names?: string[];
}

