  prefill?: Record<string, unknown>;
  domain?: TravelRuleWorkspaceDomain;
  /** Receiving Travel Rule data is free. Sending is billed only after billing is enabled. */
  billing_enabled?: boolean;
  billing_enabled_at?: Date | null;
