/** Summary row for a User Verification (KYC) session. Identity fields (`full_name`, `country`, `document_type`, `portrait_image`, contact fields) are populated progressively as the user completes verification steps, and are `null` until the relevant step finishes. Fields restricted by the workflow's response-attributes configuration are also returned as `null`. */
export interface UserSessionListItem {
  /** Unique identifier of the verification session. Use it with `GET /v3/session/{sessionId}/decision/` to fetch the full decision payload. */
  session_id: string;
  /** Row discriminator. Always `"user"` for KYC rows; Business Verification (KYB) rows have `"business"` and a different shape. */
  session_kind: "user" | (string & {});
  /** Human-friendly sequential number of the session within your application. Also matched by the `search` parameter. */
  session_number: number;
  /** Hosted verification URL the end user opens to complete the flow. `null` when the session has no hosted URL. */
  session_url: string | null;
  /** Expiring (presigned) URL of the best available portrait: the NFC chip photo when available, otherwise the ID document portrait, otherwise the liveness reference image. `null` until one of those exists. Download promptly; the link expires. */
  portrait_image: string | null;
  /** Human-readable type of the verified ID document. `null` before document verification completes, and also `null` after completion when the verified code has no display mapping (`SSC`, `WP`, `VISA`, `PSC`, `BC`, `OTHER`). Note: the `document_type` query parameter filters by short codes (`P`, `ID`, `DL`, `RP`, ...), not by these display values. */
  document_type:
    | "Passport"
    | "Identity Card"
    | "Driver's License"
    | "Residence Permit"
    | "Health Insurance Card"
    | "Tax Card"
    | (string & {})
    | null;
  /** Best available full name for the session, resolved in order: ID document OCR, AML screened data, database-validation screened data, proof-of-address document, then the expected details provided at session creation. `null` when none is available yet. */
  full_name: string | null;
  /** ISO 3166-1 alpha-3 country associated with the session, resolved in order: ID document issuing state, database-validation issuing state, proof-of-address issuing state, expected details, then the verified phone's country. May differ from nationality. */
  country: string | null;
  /** Overall session status. See the [Verification Statuses](/integration/verification-statuses) page for the lifecycle. */
  status:
    | "Not Started"
    | "In Progress"
    | "Approved"
    | "Declined"
    | "In Review"
    | "Expired"
    | "Abandoned"
    | "Kyc Expired"
    | "Resubmitted"
    | "Awaiting User"
    | (string & {});
  /** Your own identifier for the end user, echoed back exactly as sent at session creation. */
  vendor_data: string | null;
  /** Didit's internal identifier for the verified user profile behind this session. Stable across multiple sessions of the same user; filterable via the `didit_internal_id` query parameter. */
  didit_internal_id: string | null;
  /** UTC timestamp when the session was created. */
  created_at: Date;
  /** Per-feature status for every verification step configured in the session's workflow, in workflow order. */
  features: UserSessionListItemFeatures[];
  /** Phone associated with the session: the verified phone when phone verification ran, otherwise the contact phone provided at session creation. `null` when neither exists. */
  phone_number: UserSessionListItemPhoneNumber | null;
  /** Email associated with the session: the verified email when email verification ran, otherwise the contact email provided at session creation. `null` when neither exists. */
  email_address: UserSessionListItemEmailAddress | null;
  /** Compact per-feature extras. Only features that produced data appear as keys; `null` when no feature produced extras. Fields excluded by the workflow's response-attributes configuration are omitted. */
  additional_details: UserSessionListItemAdditionalDetails | null;
}

/** Compact per-feature extras. Only features that produced data appear as keys; `null` when no feature produced extras. Fields excluded by the workflow's response-attributes configuration are omitted. */
export interface UserSessionListItemAdditionalDetails {
  /** Present when AML screening ran. */
  aml?: UserSessionListItemAdditionalDetailsAml;
  /** Present when database validation ran. */
  database_validation?: UserSessionListItemAdditionalDetailsDatabaseValidation;
  /** Present when proof of address ran. */
  poa?: UserSessionListItemAdditionalDetailsPoa;
  /** Present when a liveness check ran. */
  liveness?: UserSessionListItemAdditionalDetailsLiveness;
  /** Present when face match ran. */
  face_match?: UserSessionListItemAdditionalDetailsFaceMatch;
  /** Present when phone verification ran. */
  phone_verification?: UserSessionListItemAdditionalDetailsPhoneVerification;
  /** Present when email verification ran. */
  email_verification?: UserSessionListItemAdditionalDetailsEmailVerification;
}

/** Present when AML screening ran. */
