/** A VASP of the directory or a member of the Didit network, with the routes your application has to it. A customer is a member of the Didit network only while its application is live, its Travel Rule is on, its profile is discoverable, has a legal name and a confirmed compliance email, and Didit has not marked the application as a test, demo or internal one. Each row also carries the shared due-diligence assessment (dd_score, risk_level, responsiveness, essential_checks) and your application's own decision, entity screening and questionnaires, which no other customer sees. */
export interface VaspDirectoryEntry {
  /** The entry's id, for GET /v3/travel-rule/vasps/{vasp_id}/. */
  id?: string;
  /** directory for an entry of the shared directory; didit for a member of the Didit network. */
  kind?: "directory" | "didit" | (string & {});
  name?: string;
  lei?: string;
  /** ISO 3166 country code, as the source gives it. */
  jurisdiction?: string;
  /** The VASP's web domains. Always empty for Didit network members. */
  domains?: string[];
  /** Whether your application has an available route to this VASP, or to one of its entities for a brand. Always true for a Didit network member, except on a sandbox application, where every row is false. */
  reachable?: boolean;
  /** Other names the VASP is found by. */
  aliases?: VaspDirectoryEntryAliases[];
  networks?: VaspDirectoryEntryNetworks[];
  routes?: VaspDirectoryEntryRoutes[];
  /** The brand this entry is a regulated entity of. Null when it is not part of one. */
  umbrella?: VaspDirectoryEntryUmbrella | null;
  /** For a brand, the regulated entities that receive its transfers. A transfer naming the brand goes to the reachable entity in the jurisdiction it states (beneficiary_data.counterparty_vasp_jurisdiction), else to the entity blockchain analytics attribution linked to the destination wallet, else to the only reachable entity when no jurisdiction is stated. Two entities that fit equally are never guessed between. */
  entities?: VaspDirectoryEntryEntities[];
  /** The platform's contacts for this VASP and your application's own. */
  contacts?: VaspDirectoryEntryContacts[];
  /** Didit's verification status of the entry, scored by the verification component of dd_score. Always COMPLETED for a Didit network member. */
  dd_status?: "NOT_STARTED" | "IN_PROGRESS" | "COMPLETED" | "REJECTED" | (string & {});
  /** The shared due-diligence score of a directory entry, 0 to 100, where higher is safer (see dd_score_semantic): the sum of the points in dd_score_breakdown. Null for a Didit network member, which is not scored. An entry not assessed yet (dd_assessed_at null) shows 0 with an empty risk_level, so read risk_level rather than the raw score. */
  dd_score?: number | null;
  /** Rails recorded on the entry. Read routes for what your application can use today. */
  reachable_rails?: (
    "INTERNAL" | "TRP" | "GTR" | "TRUST" | "VERIFYVASP" | "SYGNA" | "EMAIL" | (string & {})
  )[];
  /** true for a member of the Didit network (dd_status is always COMPLETED, dd_score null and risk_level empty for these) and for a directory entry linked to a Didit customer. */
  is_didit_customer?: boolean;
  /** One object per component of dd_score. Components, their weight (max) and their reason codes: jurisdiction, 25 (jurisdiction_not_high_risk, jurisdiction_high_risk, jurisdiction_unknown); verification, 15 (dd_status_completed, dd_status_in_progress, dd_status_not_started, dd_status_rejected); protocol, 15 (native_rail, email_only, no_rail); lei, 10 (lei_valid, lei_missing); history, 10 (history, no_history); essentials, 15 (essential_checks, no_essential_checks); responsiveness, 10 (responsive, unresponsive, responsiveness_unknown). Empty for a Didit network member. */
  dd_score_breakdown?: Record<string, VaspDirectoryEntryDdScoreBreakdownValue>;
  /** When dd_score, risk_level and responsiveness were last computed: after an exchange with the entry completes, finishes, expires, mismatches or is declined, when Didit refreshes or curates the entry, and in the weekly directory refresh. Null for a Didit network member. */
  dd_assessed_at?: Date | null;
  /** Which way dd_score points: always higher_is_safer. */
  dd_score_semantic?: "higher_is_safer" | (string & {});
  /** The band dd_score falls in: LOW (70 or more), MEDIUM (40 to 69) or HIGH (below 40). Empty for a Didit network member and for an entry not assessed yet. Filter on it with risk. Your own flagged screening never changes this shared value: it makes counterparty_risk_level HIGH in your rules instead. */
  risk_level?: "LOW" | "MEDIUM" | "HIGH" | "" | (string & {});
  /** Whether the VASP answers Travel Rule requests: the share of the requests Didit customers started towards it in the last 90 days that it answered. Only requests sent over a network or protocol rail, or by email to a shared address (the entry's compliance address or a platform contact), count; a request sent to an address a customer typed, or to a customer's private contact, never does. An expired request is unanswered; a completed exchange, a decline or a data mismatch is an answer; a cancelled request or an unreachable rail is neither. Always UNKNOWN with zero counts for a Didit network member. */
  responsiveness?: VaspDirectoryEntryResponsiveness;
  /** The essential-checks report of a directory entry, built only from the platform's verified sources: registration (an official register lists the VASP: the EU's interim MiCA register, the public TRISA directory or the global LEI register), licence (a MiCA authorisation is on record and current), domain (the entry's domain matches its TRP endpoint or the website its register gives) and lei (its LEI record is active, issued and consistent with the entry's names and country). The essentials component of dd_score is the share of decided checks that pass. Empty until the weekly directory refresh first checks the entry, and always empty for a Didit network member. */
  essential_checks?: VaspDirectoryEntryEssentialChecks;
  /** Your application's decision on this VASP, or for an entity with no decision of its own its brand's (inherited_from names the brand). Null when there is none. Private to your application. */
  decision?: TravelRuleCounterpartyDecision | null;
  /** Your application's latest sanctions and adverse-media screening of this VASP. Null when you never screened it. Private to your application. */
  entity_screening?: TravelRuleCounterpartyScreening | null;
  /** Your application's due-diligence questionnaires with this VASP, newest first. Private to your application. */
  questionnaires?: TravelRuleCounterpartyQuestionnaire[];
}

export interface VaspDirectoryEntryAliases {
  name?: string;
  /** trading_name, other_legal_name (from the global LEI register), network_name (the name on a Travel Rule network), attribution (the entity name blockchain analytics gives the VASP's wallets), merged (the name of a duplicate entry merged into this one) or staff. */
  kind?:
    | "trading_name"
    | "other_legal_name"
    | "network_name"
    | "attribution"
    | "merged"
    | "staff"
    | (string & {});
}

/** A compliance contact the EMAIL rail can write to. */
export interface VaspDirectoryEntryContacts {
  id?: string;
  email?: string;
  name?: string;
  /** staff: curated by Didit; application: added by your application; learned: an address that answered a Travel Rule request through its response link. */
  source?: "staff" | "application" | "learned" | (string & {});
  /** platform contacts are used for every Didit customer's transfers; application contacts are private to your application, which sees only its own. */
  scope?: "platform" | "application" | (string & {});
  /** When someone at this address answered a request. Null when it has not yet. */
  verified_at?: Date | null;
}

export interface VaspDirectoryEntryDdScoreBreakdownValue {
  /** Points the component contributes, rounded to one decimal. */
  points?: number;
  /** The component's weight: the points it contributes at best. */
  max?: number;
  /** Machine-readable code of the component's verdict. */
  reason?: string;
  /** One-line English explanation. */
  detail?: string;
}

/** A regulated entity of a brand: the legal entity that receives a transfer. */
export interface VaspDirectoryEntryEntities {
  id?: string;
  name?: string;
  lei?: string;
  jurisdiction?: string;
  /** Whether your application has an available route to it. */
  reachable?: boolean;
}

/** The essential-checks report of a directory entry, built only from the platform's verified sources: registration (an official register lists the VASP: the EU's interim MiCA register, the public TRISA directory or the global LEI register), licence (a MiCA authorisation is on record and current), domain (the entry's domain matches its TRP endpoint or the website its register gives) and lei (its LEI record is active, issued and consistent with the entry's names and country). The essentials component of dd_score is the share of decided checks that pass. Empty until the weekly directory refresh first checks the entry, and always empty for a Didit network member. */
export interface VaspDirectoryEntryEssentialChecks {
  level?: "essential" | (string & {});
  checked_at?: Date;
  checks?: VaspDirectoryEntryEssentialChecksChecks[];
  passed?: number;
  failed?: number;
  unknown?: number;
  total?: number;
}

export interface VaspDirectoryEntryEssentialChecksChecks {
  id?: "registration" | "licence" | "domain" | "lei" | (string & {});
  /** unknown when no source on record can decide the check. */
  status?: "pass" | "fail" | "unknown" | (string & {});
  /** Machine-readable code of the verdict. */
  reason?: string;
  /** One-line English explanation. */
  detail?: string;
}

/** A current listing of this VASP in a Travel Rule network's member directory. A TRISA listing says who the VASP is on TRISA; Didit has no TRISA rail, so it is never a route. */
export interface VaspDirectoryEntryNetworks {
  network?: "GTR" | "TRUST" | "VERIFYVASP" | "SYGNA" | "TRISA" | (string & {});
  /** The VASP's identifier on that network. */
  code?: string;
  /** The name the network lists the VASP under. */
  listed_name?: string;
  /** The country the network lists, when it gives one. */
  country?: string;
  /** When Didit staff verified the listing. Null for listings read from a public directory. */
  verified_at?: Date | null;
  /** When the source last showed the listing. A listing the source has not shown for three weeks is removed. */
  last_seen_at?: Date | null;
  /** Where the listing comes from: the public TRISA directory, or Didit staff. */
  source?: "trisa_directory" | "staff" | (string & {});
}

/** Whether the VASP answers Travel Rule requests: the share of the requests Didit customers started towards it in the last 90 days that it answered. Only requests sent over a network or protocol rail, or by email to a shared address (the entry's compliance address or a platform contact), count; a request sent to an address a customer typed, or to a customer's private contact, never does. An expired request is unanswered; a completed exchange, a decline or a data mismatch is an answer; a cancelled request or an unreachable rail is neither. Always UNKNOWN with zero counts for a Didit network member. */
export interface VaspDirectoryEntryResponsiveness {
  /** UNKNOWN with fewer than 5 decided requests in the window; UNRESPONSIVE when less than 10 percent of them were answered; RESPONSIVE otherwise. */
  status?: "RESPONSIVE" | "UNRESPONSIVE" | "UNKNOWN" | (string & {});
  /** Decided requests in the window that the VASP answered. */
  answered?: number;
  /** Decided requests in the window: answered plus expired. */
  total?: number;
  computed_at?: Date | null;
}

/** One way your application can deliver Travel Rule data to this VASP, in the order dispatch tries them. A network route needs a membership on that network: your own (connected in the Marketplace) or Didit's once Didit holds one. Without it the route is listed as unavailable with the reason, never as a way to reach the VASP. */
export interface VaspDirectoryEntryRoutes {
  rail?: "INTERNAL" | "TRP" | "GTR" | "TRUST" | "VERIFYVASP" | "SYGNA" | "EMAIL" | (string & {});
  status?: "available" | "unavailable" | (string & {});
  /** Why an unavailable route cannot be used: no_membership (neither you nor Didit holds a membership on that network), network_switched_off (you turned that network off in your settings) or sandbox_application (a sandbox application sends only to the Didit Test VASP, so no route is available to it). Empty when the route is available. */
  reason?: "" | "no_membership" | "network_switched_off" | "sandbox_application" | (string & {});
  /** How an available route is reached: own_membership or didit_membership for a network rail, directory for a TRP endpoint the directory verified, contact for the EMAIL rail, didit_network for a Didit network member. Empty when the route is unavailable. */
  via?:
    | ""
    | "own_membership"
    | "didit_membership"
    | "directory"
    | "contact"
    | "didit_network"
    | (string & {});
}

/** The brand this entry is a regulated entity of. Null when it is not part of one. */
export interface VaspDirectoryEntryUmbrella {
  id?: string;
  name?: string;
}

export interface VerifyEmailResponse {
  /** RS256-signed JWT. Use as `Authorization: Bearer <token>` for Account Management endpoints on `apx.didit.me/auth/v2`. */
  access_token?: string;
  /** Refresh token paired with the access token. */
  refresh_token?: string;
  /** Lifetime of the access token in seconds (default 86400). */
  expires_in?: number;
  /** Minimal organization shape returned inline by `POST /programmatic/verify-email/`. */
  organization?: OrganizationSummary;
  /** Minimal application shape returned inline by `POST /programmatic/verify-email/`. Persist the `api_key` immediately. */
  application?: ApplicationCredentialsSummary;
}

export interface WalletAddressEntry {
  uuid?: string;
  /** The wallet address; `""` for an entry imported by its hash only. Unique per application, chain and memo, comparing the address without regard to case. After you delete an entry, you can register the same address again. */
  address?: string;
  /** Chain token for the address, for example `ETH` or `BTC`. When Didit routes or registers a transfer, it matches address book entries on the wallet address and, when the transfer carries a chain, on this value too, ignoring case. A transfer's chain is `beneficiary_data.chain`, filled from the transaction's crypto chain or currency symbol (for example `ETH`) when you do not send it, or the `chain` of an after-deposit registration, so use the same token everywhere. An entry with an empty chain matches any chain. A Lightning payee (a node id or a Lightning Address) registered on bitcoin is stored lowercased on `LIGHTNING`, where Lightning transfers are matched. Known chains are stored under one canonical identifier whatever spelling you send: "ethereum", "Ethereum" and "ERC20" are all stored as ETH, "BNB Smart Chain" and "BEP20" as BNB, "tron" as TRX. An unknown chain name is kept as given. */
  chain?: string;
  /** Your internal identifier for the holder. */
  holder_vendor_data?: string;
  /** Name of the wallet holder, used for the beneficiary name match. */
  holder_name?: string;
  /** Free text, defaults to "individual". */
  entity_type?: string;
  /** Read-only. Whether ownership of this address has been proven. */
  is_ownership_verified?: boolean;
  created_at?: Date;
  /** The counterparty VASP's travel address for this wallet, if known. Lets Didit route this beneficiary's transfers over the TRP rail, for the assets TRP carries (BTC, ETH, and USDC on a named network). */
  travel_address?: string;
  /** Read-only. SHA-256 of the lowercased address, in lowercase hex. An entry imported by its hash only is matched on it. */
  address_hash?: string;
  /** The destination tag or memo that is part of the wallet on a memo network (XRP, XLM, EOS, ATOM, HBAR); `""` for the whole address. An entry with a memo matches only transfers naming that memo; one without matches the whole address. */
  memo?: string;
  /** Your per-wallet travel address for this wallet: give it to the sending VASP so its TRP inquiry names this wallet. Empty for a wallet recorded as another VASP's, while Travel Rule is off, and before your VASP profile is saved. */
  receiving_travel_address?: string;
}

/** PATCH is a partial update; the response echoes only holder_name, holder_vendor_data, entity_type, travel_address, receiving_travel_address, label, and owner_type. */
export interface WalletAddressEntryUpdate {
  holder_name?: string;
  holder_vendor_data?: string;
  entity_type?: string;
  travel_address?: string;
}

/** What happened to each row of an import, in the order sent. */
export interface WalletAddressImportReport {
  total?: number;
  created?: number;
  existing?: number;
  duplicate?: number;
  failed?: number;
  rows?: WalletAddressImportReportRows[];
}

export interface WalletAddressImportReportRows {
  /** The row's number, from 1. */
  row?: number;
  /** `created`: added to the book. `existing`: the wallet is already in the book and was left untouched. `duplicate`: repeats an earlier row of this import. `failed`: see `errors`. */
  status?: "created" | "existing" | "duplicate" | "failed" | (string & {});
  /** The address-book entry the row created or found. */
  entry_id?: string | null;
  /** Field errors of a `failed` row; empty otherwise. */
  errors?: Record<string, unknown>;
  /** On a `duplicate` row, the row it repeats. */
  duplicate_of_row?: number | null;
}

export interface WalletScreeningResult {
  /** Provider that performed the screening (e.g. `merklescience`, `crystal`). */
  provider: string;
  /** Always `WALLET_SCREENING` for this endpoint. */
  screening_type: "WALLET_SCREENING" | (string & {});
  /** Normalised 0-100 risk score. Higher means greater exposure to risky entities. Merkle Science grades an address 0-5, which maps to 0, 15, 35, 55, 75 or 95. */
  risk_score: number;
  /** Risk bucket derived from `risk_score`: `0-9` UNKNOWN, `10-39` LOW, `40-69` MEDIUM, `70-89` HIGH, `90-100` CRITICAL. `UNKNOWN` is the lowest band, not a separate no-data state: `risk_score` 0 (the common clean-address case) means no adverse assessment, while a non-zero score in the 1-9 range is a real but sub-LOW signal - read the `risk_score`, not just the band. Never treat `UNKNOWN` as an affirmative low-risk or clear rating; do not display it as a pass. */
  severity: "UNKNOWN" | "LOW" | "MEDIUM" | "HIGH" | "CRITICAL" | (string & {});
  /** Screening outcome status. */
  status: "SCREENED" | "PENDING" | "ERROR" | (string & {});
  /** Human-readable summary of the screening result. */
  summary: string;
  /** The screened address, echoed back. */
  wallet_address: string;
  /** Transaction screening field, shared with the result shape. Always `null` on a wallet screening result. */
  transaction_hash?: string | null;
  /** The blockchain that was screened. */
  blockchain: string;
  /** Transaction screening field, shared with the result shape. Always `null` on a wallet screening result. */
  block_timestamp?: string | null;
  /** Transaction screening field, shared with the result shape. Always `null` on a wallet screening result. */
  total_value_usd?: number | null;
  /** Transaction screening field, shared with the result shape. Always `null` on a wallet screening result. */
  fee_usd?: number | null;
  /** Transaction screening field, shared with the result shape. Always empty on a wallet screening result. */
  sender_rows?: Record<string, unknown>[];
  /** Transaction screening field, shared with the result shape. Always empty on a wallet screening result. */
  receiver_rows?: Record<string, unknown>[];
  /** Transaction screening field, shared with the result shape. Always empty on a wallet screening result. */
  transaction_flows?: Record<string, unknown>[];
  /** Transaction screening field, shared with the result shape. Always `null` on a wallet screening result. */
  transaction_flows_status?: string | null;
  /** Transaction screening field, shared with the result shape. Always `null` on a wallet screening result. */
  transaction_flows_error?: string | null;
  /** Where the address received funds from, attributed by entity. Each entry is an exposure breakdown. */
  source_of_funds: WalletScreeningResultSourceOfFunds[];
  /** Where the address sent funds to, attributed by entity. Same item shape as `source_of_funds` with `exposure_direction` = `outgoing`. */
  destination_of_funds: WalletScreeningResultDestinationOfFunds[];
  /** Entities the provider attributes the screened address to. For Merkle Science these come from the address's own owner and user tags, so the same entity can appear twice, and they carry no fund flows: `received_usd`, `sent_usd`, `received_hops` and `sent_hops` are `null` and `percentage` is 0. Do not route on `risk_level` or `is_direct` here: use `sanctions_hit`, `dominant_risk_category` and `risk_factors[].is_high_risk` for the verdict, and `exposure_type` in `source_of_funds`/`destination_of_funds` for directness. */
  counterparty_connections: WalletScreeningResultCounterpartyConnections[];
  /** Exposure graph nodes for transaction screening. Empty on a wallet screening result. */
  network_nodes?: Record<string, unknown>[];
  /** Exposure graph edges for transaction screening. Empty on a wallet screening result. */
  network_edges?: Record<string, unknown>[];
  /** True if the address has direct or indirect sanctions exposure. */
  sanctions_hit: boolean;
  /** Politically exposed person exposure. `null` when no PEP finding is available, which is every result today because no provider reports one; `false` only for an explicit negative screening result. Do not read `null` as a completed PEP check. */
  pep_counterparty?: boolean | null;
  /** Highest-weighted high-risk category, or `null` when none is dominant (e.g. `sanctioned`, `mixer`, `stolen_funds`). */
  dominant_risk_category: string | null;
  /** Ranked explanation of `risk_score`: what produced this verdict. Providers grade an address on their own model and return only a verdict (Merkle Science returns an integer 0-5), so the score alone is not actionable. Ordered high-risk first, then by the value that moved through each driver, capped at the five strongest; `source_of_funds` and `destination_of_funds` always carry the complete breakdown. A high `risk_score` with no `is_high_risk` entry means the provider reported no sanctions or attributed-entity match and graded the address purely on its own exposure model - `summary` states this explicitly. */
  risk_factors?: WalletScreeningResultRiskFactors[];
  /** The provider's own payload. Its shape is provider-specific and can change without notice: read the normalised fields instead of parsing it. */
  raw_response?: Record<string, unknown>;
  /** Opaque HMAC-SHA256 signature over this exact result, scoped to your application. Not meaningful on its own - repost the full response body, unmodified and including this field, to `POST /v3/wallet-screening/pdf/` to render it as a PDF. The PDF endpoint rejects the request with `400` if `report_signature` is missing or if any signed field (e.g. `risk_score`, `severity`, `sanctions_hit`) was edited before repost. */
  report_signature: string;
}

export interface WalletScreeningResultCounterpartyConnections {
  /** Attributed entity name. */
  entity_name?: string | null;
  /** Provider entity type. */
  entity_type?: string | null;
  /** Provider entity subtype. */
  entity_subtype?: string | null;
  /** Lowercase and provider-dependent. For Merkle Science it is the address's own 0-5 risk grade (`no_risk`, `low`, `medium_low`, `medium`, `high`, `critical`), raised to `high` when the entity's category is high risk; it is not a separate grade of the entity. */
  risk_level?: string;
  /** Normalised risk categories of the entity. */
  categories?: string[];
  /** USD received from the entity, when the provider reports it. */
  received_usd?: number | null;
  /** USD sent to the entity, when the provider reports it. */
  sent_usd?: number | null;
  /** Hops to the entity on the receiving side, when the provider reports them. */
  received_hops?: number | null;
  /** Hops to the entity on the sending side, when the provider reports them. */
  sent_hops?: number | null;
  /** Share of the address's exposure, when the provider reports it; otherwise 0. */
  percentage?: number;
  /** Always `true` for Merkle Science, whose connections are attributions rather than counterparties. */
  is_direct?: boolean;
  /** Country of the entity, when known. */
  country?: string | null;
  /** The provider's own identifier for the entity. */
  provider_entity_id?: string | null;
}

export interface WalletScreeningResultDestinationOfFunds {
  /** Normalised risk category, e.g. `exchange_licensed`, `dex`, `defi`, `payment_processor`, `mixer`, `darknet_market`, `sanctioned`, `stolen_funds`, `high_risk_exchange`. */
  category?: string;
  /** Share of the direction's total exposure, 0-100. */
  percentage?: number;
  /** USD value attributed to this entity. */
  amount_usd?: number | null;
  /** Name of the attributed entity, for example an exchange, a mixer or a sanctioned group. */
  entity_name?: string | null;
  /** Provider entity type (e.g. `Exchange`, `DeFi`, `Sanctions`, `Theft`). */
  entity_type?: string | null;
  /** More granular subtype (e.g. `Mandatory KYC and AML`, `OFAC`, `Yield Aggregator`). */
  entity_subtype?: string | null;
  /** Number of hops to the entity (1 for a direct counterparty), when the provider reports one. Always `null` for Merkle Science, which reports only whether exposure is direct or indirect: use `exposure_type`. */
  hops?: number | null;
  /** `entity_type / entity_subtype`, as the provider labels the entity. */
  description?: string | null;
  /** True when `exposure_type` is `direct`. */
  is_direct?: boolean;
  /** Whether the funds came from (`incoming`) or went to (`outgoing`) this entity. */
  exposure_direction?: "incoming" | "outgoing" | "connected" | (string & {});
  /** `direct` (1 hop) or `indirect` (multi-hop) exposure. */
  exposure_type?: "direct" | "indirect" | (string & {});
  /** The provider's own identifier for the entity. */
  provider_entity_id?: string | null;
  /** The provider's own identifier for `entity_type`. */
  provider_entity_type_id?: string | null;
  /** The provider's own identifier for `entity_subtype`. */
  provider_entity_subtype_id?: string | null;
  /** Primary ISO 3166-1 alpha-2 country of the entity. Empty or `null` when the provider does not know it. */
  country?: string | null;
  /** Amount in the asset's own unit, when the provider reports it. */
  raw_amount?: number | null;
  /** Unit of `raw_amount`, when the provider reports it. */
  raw_currency?: string | null;
}

export interface WalletScreeningResultRiskFactors {
  /** `attribution` is what the provider says the address itself is (its own tag or cluster); `exposure` is where its funds actually moved. */
  source?: "attribution" | "exposure" | (string & {});
  /** Normalised risk category, same vocabulary as the exposure breakdown. */
  category?: string;
  /** The provider's own wording for the driver (e.g. `Gambling / Crypto only`), which is what you would also see in the provider's console. */
  label?: string;
  /** Attributed entity behind the driver, for example a gambling site or an exchange. */
  entity_name?: string | null;
  /** Direction of the fund flow, `attribution` when the driver is the address's own tag, or `unknown` when the provider did not report a direction. */
  direction?: "incoming" | "outgoing" | "connected" | "unknown" | "attribution" | (string & {});
  /** `direct` (1 hop) or `indirect` (multi-hop), `attribution` for the address's own tag, or `unknown` when the provider did not state how many hops away the counterparty is. Treat `unknown` as unclassified, not as `direct`. */
  exposure_type?: "direct" | "indirect" | "unknown" | "attribution" | (string & {});
  /** USD value attributed to this driver. */
  amount_usd?: number | null;
  /** Share of the address's TOTAL screened volume, both directions combined - unlike `percentage` inside `source_of_funds`/`destination_of_funds`, which is normalised per direction. Comparable and summable across the whole list. */
  percentage?: number;
  /** Whether the category is one Didit treats as high risk (`sanctioned`, `mixer`, `stolen_funds`, `ransomware`, `scam`, `darknet_market`, `terrorist_financing`, `child_exploitation`, `hacked_exchange`, `high_risk_exchange`, `seized_funds`). */
  is_high_risk?: boolean;
  /** One-line rendering of the driver, e.g. `9.01% indirect outgoing exposure to Gambling / Crypto only (Example Gambling)`. */
  description?: string;
}

export interface WalletScreeningResultSourceOfFunds {
  /** Normalised risk category, e.g. `exchange_licensed`, `dex`, `defi`, `payment_processor`, `mixer`, `darknet_market`, `sanctioned`, `stolen_funds`, `high_risk_exchange`. */
  category?: string;
  /** Share of the direction's total exposure, 0-100. */
  percentage?: number;
  /** USD value attributed to this entity. */
  amount_usd?: number | null;
  /** Name of the attributed entity, for example an exchange, a mixer or a sanctioned group. */
  entity_name?: string | null;
  /** Provider entity type (e.g. `Exchange`, `DeFi`, `Sanctions`, `Theft`). */
  entity_type?: string | null;
  /** More granular subtype (e.g. `Mandatory KYC and AML`, `OFAC`, `Yield Aggregator`). */
  entity_subtype?: string | null;
  /** Number of hops to the entity (1 for a direct counterparty), when the provider reports one. Always `null` for Merkle Science, which reports only whether exposure is direct or indirect: use `exposure_type`. */
  hops?: number | null;
  /** `entity_type / entity_subtype`, as the provider labels the entity. */
  description?: string | null;
  /** True when `exposure_type` is `direct`. */
  is_direct?: boolean;
  /** Whether the funds came from (`incoming`) or went to (`outgoing`) this entity. */
  exposure_direction?: "incoming" | "outgoing" | "connected" | (string & {});
  /** `direct` (1 hop) or `indirect` (multi-hop) exposure. */
  exposure_type?: "direct" | "indirect" | (string & {});
  /** The provider's own identifier for the entity. */
  provider_entity_id?: string | null;
  /** The provider's own identifier for `entity_type`. */
  provider_entity_type_id?: string | null;
  /** The provider's own identifier for `entity_subtype`. */
  provider_entity_subtype_id?: string | null;
  /** Primary ISO 3166-1 alpha-2 country of the entity. Empty or `null` when the provider does not know it. */
  country?: string | null;
  /** Amount in the asset's own unit, when the provider reports it. */
  raw_amount?: number | null;
  /** Unit of `raw_amount`, when the provider reports it. */
  raw_currency?: string | null;
}

/** Application-level webhook configuration, retention policy and Digital ID wallet return hosts, with every webhook destination. */
export interface WebhookConfig {
  /** Application-level (legacy) webhook URL. Didit sends to it only while the application has no enabled destination, and then only `status.updated` and `data.updated`. Every create, update or delete of a destination sets it to the URL of the oldest enabled destination, or `null` when none is enabled. */
  webhook_url: string | null;
  /** Payload version of the legacy `webhook_url`. Each destination has its own `webhook_version`. */
  webhook_version: "v1" | "v2" | "v3" | (string & {});
  /** Application-level signing secret (43-character URL-safe token). It signs only deliveries to the legacy `webhook_url`; each destination signs with its own `secret_shared_key`. API-key callers always receive it in full; Console users without `read:webhooks` receive an empty string. */
  secret_shared_key: string;
  /** Legacy application setting. The verification flow does not read it: capture options are configured per workflow. */
  capture_method: "MOBILE" | "MOBILE_AND_DESKTOP" | (string & {});
  /** Automatic deletion window. User verification sessions created more than this many months ago (a month counts as 30 days) are deleted automatically, and that deletion is irreversible. `null` means sessions are never deleted automatically. See [Data retention](https://docs.didit.me/console/data-retention). */
  data_retention_months: number | null;
  /** What happens to a session's face embedding when the session is deleted. `delete_with_session` (default) deletes it with the session. `retain_until_user_deleted` is the opt-in [biometric template retention](https://docs.didit.me/console/data-retention#biometric-template-retention): an image-free biometric template linked to the User is managed separately until its retention period ends, the User is deleted, or you purge it. */
  face_retention_policy: "delete_with_session" | "retain_until_user_deleted" | (string & {});
  /** Retention period, in days, of biometric templates under `retain_until_user_deleted`. Required when that policy is set. */
  face_retention_days: number | null;
  /** When the hosted flow and the native SDKs ask the person for explicit biometric consent before a face capture. `auto` (default) asks only where a trigger applies: a declared state, the person's IP, or the identity document's issuer is in Illinois, Texas or Colorado, or the person looks to be in the US without a known state. `always` asks every person whose workflow captures a face. `never` never shows the step, and you collect consent yourself before the selfie. Each change is recorded in the audit log. See [Biometric consent](https://docs.didit.me/getting-started/biometric-consent). */
  biometric_consent_mode?: "auto" | "always" | "never" | (string & {});
  /** Every event type a destination can subscribe to, with a display label. */
  available_events: WebhookConfigAvailableEvents[];
  /** Hostnames (exact match, HTTPS only) a standalone Digital ID wallet verification may send the user back to with its `return_url`. Your white-label domain is always allowed as well. See [Register your return destination](https://docs.didit.me/standalone-apis/digital-id-wallets#register-your-return-destination). */
  allowed_return_hosts: string[];
  /** Every webhook destination of the application, oldest first, each with its signing secret. Read only here: manage destinations with the `/v3/webhook/destinations/` endpoints. */
  endpoints: WebhookConfigDestination[];
}

export interface WebhookConfigAvailableEvents {
  /** Supported webhook event name. Use these exact strings in `subscribed_events`; unsupported values are rejected. */
  value: WebhookEventType;
  /** Display label, for example `Session status updated`. */
  label: string;
}

/** A webhook destination as listed in the webhook configuration, without delivery metrics. `GET /v3/webhook/destinations/{destination_uuid}/` adds its delivery summary. */
export interface WebhookConfigDestination {
  /** Destination ID. */
  uuid: string;
  /** Human-readable name. */
  label: string;
  /** HTTPS endpoint Didit posts events to. */
  url: string;
  /** `false` pauses deliveries to this destination. */
  enabled: boolean;
  /** Payload version sent to this destination. */
  webhook_version: "v1" | "v2" | "v3" | (string & {});
  /** This destination's signing secret (43-character URL-safe token). Verify each webhook with the secret of the destination it was sent to. API-key callers always receive it in full; Console users without `read:webhooks` receive an empty string. */
  secret_shared_key: string;
  /** Event types delivered to this destination. Empty when the destination was created without events, in which case it receives nothing. */
  subscribed_events: WebhookEventType[];
  created_at: Date;
  updated_at: Date;
}

/** One delivery attempt to a webhook destination. The first send of an event, each automatic retry and each resend are separate deliveries. */
export interface WebhookDestinationDelivery {
  /** Delivery ID, for the detail and resend calls. */
  uuid: string;
  /** User verification session the event is about. `null` for business session, user, business, transaction, Travel Rule and workflow events. */
  session_id: string | null;
  /** URL the delivery was sent to: the destination's URL when the event was generated. */
  request_url: string | null;
  /** HTTP status your endpoint returned. `null` while the delivery is queued and not yet attempted. When no HTTP answer was received Didit records a status of its own: `504` when your endpoint did not answer within 5 seconds, `503` for a connection failure, `400` when the URL was refused as unsafe (for example a private or internal address), and `404` for any other request error. `400` or above counts as a failed delivery. */
  response_status: number | null;
  /** Time the attempt took, in milliseconds. `null` while the delivery is queued. */
  response_time_ms: number | null;
  /** Status the event reported when it was generated: the session status for session events (for example `Approved` or `In Review`), the person's or company's status for user and business events, and the transaction status for transaction events. `null` for events that carry no status. */
  status: string | null;
  /** Supported webhook event name. Use these exact strings in `subscribed_events`; unsupported values are rejected. */
  webhook_type: WebhookEventType;
  /** When the delivery was created. */
  created_at: Date;
}

/** One delivery attempt to a webhook destination, with the exact request headers and body Didit sent. */
export interface WebhookDestinationDeliveryDetail {
  /** Delivery ID, for the detail and resend calls. */
  uuid: string;
  /** User verification session the event is about. `null` for business session, user, business, transaction, Travel Rule and workflow events. */
  session_id: string | null;
  /** URL the delivery was sent to: the destination's URL when the event was generated. */
  request_url: string | null;
  /** HTTP status your endpoint returned. `null` while the delivery is queued and not yet attempted. When no HTTP answer was received Didit records a status of its own: `504` when your endpoint did not answer within 5 seconds, `503` for a connection failure, `400` when the URL was refused as unsafe (for example a private or internal address), and `404` for any other request error. `400` or above counts as a failed delivery. */
  response_status: number | null;
  /** Time the attempt took, in milliseconds. `null` while the delivery is queued. */
  response_time_ms: number | null;
  /** Status the event reported when it was generated: the session status for session events (for example `Approved` or `In Review`), the person's or company's status for user and business events, and the transaction status for transaction events. `null` for events that carry no status. */
  status: string | null;
  /** Supported webhook event name. Use these exact strings in `subscribed_events`; unsupported values are rejected. */
  webhook_type: WebhookEventType;
  /** When the delivery was created. */
  created_at: Date;
  /** JSON text (a string) of the request headers Didit sent: `Content-Type`, `X-Signature`, `X-Signature-V2`, `X-Signature-Simple`, `X-Timestamp` and `User-Agent`. Parse it with a JSON parser. It holds signatures, never the signing secret. */
  request_header: string;
  /** JSON text (a string) of the exact payload Didit sent, keys sorted, including `event_id` and `timestamp`. Parse it with a JSON parser; see [Payload shape](https://docs.didit.me/integration/webhooks#payload-shape). For a scoped key without `media: read`, media URLs inside it are `null`; without `sessions: write`, session tokens and hosted verification links are `null`. A body changed that way no longer matches its signatures. Didit does not record the response body your endpoint returned. */
  request_body: string;
}

/** Supported webhook event name. Use these exact strings in `subscribed_events`; unsupported values are rejected. */
export type WebhookEventType =
  | "status.updated"
  | "data.updated"
  | "user.status.updated"
  | "user.data.updated"
  | "business.status.updated"
  | "business.data.updated"
  | "activity.created"
  | "transaction.created"
  | "transaction.status.updated"
  | "travel_rule.status.updated"
  | "workflow.compliance_changed"
  | "auth.signup"
  | "auth.login"
  | "auth.login_failed"
  | "auth.password_reset_requested"
  | "auth.password_reset_completed"
  | "auth.mfa_changed"
  | "auth.new_device"
  | "auth.account_locked"
  | "investigator.report.ready"
  | "investigator.decision.automated"
  | "investigator.decision.overridden"
  | "investigator.decision.contested"
  | "investigator.question.raised"
  | "investigator.automation.paused"
  | "investigator.rfi.answered"
  | "investigator.rfi.overdue"
  | "investigator.drift.detected"
  | "investigator.sla.breached"
  | "investigator.qa.failed"
  | "investigator.external.report.ready"
  | (string & {});

/** Event filter for this webhook destination. Didit delivers only webhooks whose event type exactly matches one of these values - there is no wildcard subscription. When sent, the list must contain at least one valid event (an explicit `[]` is rejected with 400); a destination whose list is empty (field omitted at create) receives nothing. On update the list is replaced wholesale, never merged. */
export type WebhookSubscribedEvents = WebhookEventType[];

/** The fields below are typed; the object also carries every other column of the workflow configuration (feature toggles, thresholds, warning actions, allowed documents, callbacks) as additional properties. Fields that do not apply to the `workflow_type` are `null`. */
export interface WorkflowDetail {
  /** Per-version identifier (`settings_uuid`). Every version of a workflow has its own. */
  uuid?: string;
  /** Stable identifier shared by every version of the workflow. Sessions created with it use the latest published version. */
  workflow_id?: string;
  /** Display name of the workflow. */
  workflow_label?: string;
  /** Workflow template. `null` for graph workflows created without a template. */
  workflow_type?:
    | "kyc"
    | "kyb"
    | "adaptive_age_verification"
    | "biometric_authentication"
    | "address_verification"
    | "questionnaire_verification"
    | "email_verification"
    | "phone_verification"
    | (string & {})
    | null;
  /** Whether this is the application's default workflow. */
  is_default?: boolean;
  /** Archived workflows cannot start new sessions. */
  is_archived?: boolean;
  /** Version number within the workflow. */
  version?: number;
  /** Draft versions are editable; published versions are immutable and used for new sessions. */
  status?: "draft" | "published" | (string & {});
  /** When this version was published. `null` for drafts. */
  published_at?: Date | null;
  /** `true` when the workflow has no custom `workflow_graph`. */
  is_simple_workflow?: boolean;
  /** `true` only for `draft` versions. */
  is_editable?: boolean;
  /** Public URL that starts a session with this workflow. */
  workflow_url?: string;
  /** Graph structure of the workflow (nodes and edges). `null` for simple workflows. */
  workflow_graph?: Record<string, unknown> | null;
  /** Enabled features joined with `" + "`, for example `"OCR + LIVENESS"`. */
  features?: string;
  /** Price per session; for graph workflows the most expensive path. */
  total_price?: number | null;
  /** Price of the cheapest path through the workflow. */
  min_price?: number | null;
  /** Price of the most expensive path through the workflow. */
  max_price?: number | null;
  /** Organization-specific add-on prices, or `null` when none are set. */
  special_add_on_prices?: Record<string, unknown> | null;
  /** Retries allowed after a declined verification. */
  max_retry_attempts?: number;
  /** Days during which the retries are allowed. */
  retry_window_days?: number | null;
  /** Seconds before an unfinished session expires. */
  session_expiration_time?: number;
  /** The questionnaire attached to the workflow, or `null`. */
  questionnaire?: Record<string, unknown> | null;
  /** Per-role verification settings for KYB key people. */
  kyb_role_settings?: Record<string, unknown>[];
  created_at?: Date;
  updated_at?: Date;
  /** Whether a simple KYC or KYB workflow runs Bank verification. It runs after the contact steps (and Location verification) and before database validation, AML and IP analysis. Bank verification is not generally available yet: turning it on is refused wherever it is not enabled. */
  is_bank_verification_enabled?: boolean;
  /** Bank verification settings of a simple workflow, with the same keys a `BANK_VERIFICATION` node takes (for example `bank_countries` and `bank_method_order`). Unknown keys are dropped. Every key is optional and an absent key keeps its default, so `{}` means all defaults. See [Bank verification settings](/management-api/workflows/feature-configs#bank-verification). */
  bank_verification_config?: Record<string, unknown>;
  /** Whether a simple KYC workflow runs Location verification. It runs after the contact steps and before Bank verification and database validation. Business (KYB) workflows cannot run it. */
  is_geolocation_enabled?: boolean;
  /** Location verification settings of a simple workflow, with the same keys a `GEOLOCATION` node takes (for example `is_geolocation_geofencing_enabled` and `geolocation_max_attempts`). Unknown keys are dropped. Every key is optional and an absent key keeps its default, so `{}` means all defaults. */
  geolocation_config?: Record<string, unknown>;
  [key: string]: unknown;
}

/** One workflow version in the list view. */
export interface WorkflowListItem {
  /** Per-version UUID. Use as `{settings_uuid}` for get/update/delete, and as `workflow_id` when creating sessions. */
  uuid?: string;
  /** Stable group ID shared by every version of the same workflow. Equals `uuid` for version 1. */
  workflow_id?: string;
  /** Display name for the workflow. */
  workflow_label?: string;
  /** Base type for simple workflows: `kyc`, `kyb`, `adaptive_age_verification`, `biometric_authentication`, etc. `null` for graph-based workflows without a KYB feature. */
  workflow_type?: string | null;
  /** Whether this is the default workflow for new sessions. */
  is_default?: boolean;
  is_archived?: boolean;
  /** Whether white-label customization applies to sessions created with this workflow. */
  is_white_label_enabled?: boolean;
  /** Fixed price per verification in USD (JSON number, excludes variable-priced features such as DATABASE_VALIDATION and PHONE_VERIFICATION). */
  total_price?: number;
  /** Cheapest fixed price across workflow-graph paths, in USD. */
  min_price?: number;
  /** Most expensive fixed price across workflow-graph paths, in USD. */
  max_price?: number;
  /** Enabled features as a single `" + "`-joined string, e.g. `"OCR + LIVENESS + FACE_MATCH"`. Split on `" + "` to get a list. */
  features?: string;
  /** True when the workflow has no custom workflow graph. */
  is_simple_workflow?: boolean;
  /** True when this version is a `draft` (drafts are editable in place; published versions are immutable in the Console). */
  is_editable?: boolean;
  /** Public shareable verification URL for this workflow (`https://verify.didit.me/u/<token>`). */
  workflow_url?: string;
  /** Maximum retry attempts allowed after a declined verification (0-10). */
  max_retry_attempts?: number;
  /** Rolling window in days used to count retries (1-365). `null` = all-time limit. */
  retry_window_days?: number | null;
  /** Seconds before an unfinished session expires (3600-2419200). */
  session_expiration_time?: number;
  /** Version number within the `workflow_id` group, starting at 1. */
  version?: number;
  /** Version status. New sessions use the latest `published` version of a group. */
  status?: "draft" | "published" | (string & {});
  /** True when any version in this `workflow_id` group is currently a draft. */
  has_draft?: boolean;
  /** Who created this version: `{name, email, type}` where `type` is `user` (Console user, `email` set) or `api_key` (`name` is the client id, `email` is null). `null` when no creator was recorded. */
  created_by?: WorkflowListItemCreatedBy | null;
  updated_at?: Date;
}

/** Who created this version: `{name, email, type}` where `type` is `user` (Console user, `email` set) or `api_key` (`name` is the client id, `email` is null). `null` when no creator was recorded. */
export interface WorkflowListItemCreatedBy {
  name?: string;
  email?: string | null;
  type?: "user" | "api_key" | (string & {});
}
